import {regions,geoStops} from './coastal-geography.js';
import {flagUrl,countryLearning} from './coastal-learning.js';
import {stationArt,stationArtUrl} from './coastal-station-art.js';
export function installTravelJournal({root,side,state,node,mission,count,bar,task,wallet,pressure,message,routes,mapKey,runCards,learningUI,vehiclePicture,refresh,roundDuration,stationStats,draw}){
 side.classList.add('coastal-journal');let country=0,lastRound=0,key='';
 const heading=node('header',null,'coastal-journal-heading');heading.append(node('span','✦ FIELD NOTES'),node('h3','Travel journal'),node('span','Explore · Connect · Discover'));
 const progress=node('section',null,'coastal-journal-progress'),roundRow=node('div',null,'coastal-journal-round'),timer=node('span'),track=node('div',null,'coastal-journal-track'),bus=vehiclePicture('road',1),dots=node('div');
 for(let i=0;i<11;i++)dots.append(node('span'));track.append(dots,bus,node('span','⚑','coastal-journal-finish'));roundRow.append(mission,timer);progress.append(roundRow,node('span','Delivery progress','coastal-journal-kicker'),track,count,bar);
 const queues=node('section',null,'coastal-journal-queues');queues.setAttribute('aria-label','Stations needing attention');let queueKey='';
 const postcard=node('section',null,'coastal-postcard'),title=node('h3'),flag=node('img'),capital=node('strong'),picture=node('img'),caption=node('p'),fact=node('p'),open=node('button','Open atlas →','coastal-atlas-button'),previous=node('button','‹'),next=node('button','›'),position=node('span'),navigation=node('div',null,'coastal-postcard-nav');
 flag.className='coastal-postcard-flag';picture.className='coastal-postcard-picture';picture.decoding='async';fact.className='coastal-postcard-fact';caption.className='coastal-postcard-caption';open.type='button';previous.type=next.type='button';previous.setAttribute('aria-label','Previous country postcard');next.setAttribute('aria-label','Next country postcard');navigation.append(previous,position,next);postcard.append(title,picture,caption,flag,capital,fact,open,navigation);open.onclick=()=>learningUI.openAtlas(regions.filter(r=>r.round<=state.round)[country].id);
 function cycle(delta){const known=regions.filter(r=>r.round<=state.round);country=(country+delta+known.length)%known.length;key='';update();}previous.onclick=()=>cycle(-1);next.onclick=()=>cycle(1);
 const shortcuts=node('nav',null,'coastal-journal-shortcuts');shortcuts.setAttribute('aria-label','Journal tools');
 function popup(label,content){const d=node('dialog',null,'coastal-shop coastal-journal-shop'),close=node('button','Close '+label.toLowerCase()+' ×'),launch=node('button',label);let resume=false;d.setAttribute('aria-label',label);close.onclick=()=>d.close();close.type=launch.type='button';d.append(close,node('h3',label),content);root.append(d);launch.onclick=()=>{resume=state.running;state.running=false;refresh();d.showModal();};d.addEventListener('close',()=>{if(resume&&!state.complete&&!state.failed)state.running=true;resume=false;refresh();});return launch;}
 const routeButton=popup('Manage routes',routes);routes.open=true;
 const briefing=node('div',null,'coastal-journal-briefing');briefing.append(task,wallet,pressure);const helpButton=popup('Help',briefing);briefing.append(node('p','Drag between stops to build a line. Click a city to upgrade its station. Click landmark drawings to learn about places. Open the atlas to explore flags, capitals and waterways. Reading pauses your game.'));
 for(const [button,label,icon]of [[routeButton,'Manage routes','🚌'],[mapKey.launch,'Map key','📖'],[runCards.launch,'Run cards','🃏'],[helpButton,'Help','🧭']]){button.setAttribute('aria-label',button===mapKey.launch?'Map key · countries and capitals':button===runCards.launch?'Your run cards':label);button.replaceChildren(node('span',icon),node('strong',label),node('span','›'));shortcuts.append(button);}
 side.querySelector('.coastal-atlas-button')?.remove();
 const extras=node('details',null,'coastal-journal-extras');extras.append(node('summary','Network tools'));for(const button of [...side.children].filter(el=>el.tagName==='BUTTON'))extras.append(button);
 const tutorial=side.querySelector('.coastal-tutorial'),event=side.querySelector('.coastal-event-notice'),shapes=side.querySelector('.coastal-shape-filter');
 side.replaceChildren(heading,progress);if(event)side.append(event);if(shapes){shapes.open=true;side.append(shapes);}side.append(queues,postcard,shortcuts,extras);if(tutorial)side.append(tutorial);message.classList.add('coastal-journal-message');side.append(message);
 function update(){
  const known=regions.filter(r=>r.round<=state.round);if(lastRound!==state.round){if(!lastRound||known.some(r=>r.round>lastRound)){country=known.findIndex(r=>r.round===Math.max(...known.map(r=>r.round)));}lastRound=state.round;}
  const seconds=Math.ceil(Math.max(0,roundDuration(state)-state.elapsed));timer.textContent='◷ '+Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');bus.style.left=Math.min(100,state.delivered/state.target*100)+'%';for(const [i,dot]of [...dots.children].entries())dot.dataset.done=String(i/10<=state.delivered/state.target);
  const crowded=state.activeStops.map(id=>({id,count:state.passengers.filter(p=>p.at===id&&['waiting','boarding'].includes(p.mode)).length,danger:state.danger[id]??0})).filter(q=>q.danger||q.count>=Math.ceil(stationStats(state,q.id).queue*.7)).sort((a,b)=>b.danger-a.danger||b.count-a.count).slice(0,2),nextQueueKey=JSON.stringify(crowded.map(q=>[q.id,q.count,Math.ceil(q.danger)]));
  if(queueKey!==nextQueueKey){queueKey=nextQueueKey;queues.replaceChildren();if(!crowded.length)queues.append(node('span','✓ Stations flowing'));for(const q of crowded){const b=node('button');b.type='button';b.dataset.urgent=String(q.danger>0);b.append(node('strong',geoStops[q.id].name),node('span',q.danger?Math.max(0,Math.ceil(stationStats(state,q.id).alarm-q.danger))+'s to clear':q.count+' waiting'),node('span','→'));b.setAttribute('aria-label','Focus '+geoStops[q.id].name+' · '+q.count+' waiting');b.onclick=()=>{const city=geoStops[q.id];state.camera.x=500-city.x*state.camera.zoom;state.camera.y=300-city.y*state.camera.zoom;state.cameraReady=true;draw();};queues.append(b);}}
  const r=known[country],nextKey=r.id+'|'+state.round;if(nextKey===key)return;key=nextKey;const city=geoStops.find(s=>s.region===r.id&&s.capital),art=stationArt[city.id];postcard.dataset.discoverCountry=r.id;title.textContent='Discover '+r.name;flag.src=flagUrl(r.id);flag.alt=r.id==='northern-ireland'?'Union Flag of the United Kingdom':r.name+' flag';capital.textContent='Capital · '+r.capital;picture.src=stationArtUrl(city.id);picture.alt=art.landmark+' in '+r.capital;caption.textContent=art.landmark;fact.textContent=countryLearning[r.id].extra[0]??r.facts[1];position.textContent=(country+1)+' / '+known.length+' countries';previous.disabled=next.disabled=known.length===1;
 }
 return {refresh:update};
}
